"use client";

import { PreviewCard as PreviewCardPrimitive } from "@base-ui/react/preview-card";
import { cn } from "@/lib/cn";
import { useJkPortalContainer } from "@/lib/portal-container";
import type {
  HoverCardContentProps,
  HoverCardProps,
  HoverCardTriggerProps,
} from "./HoverCard.types";

function HoverCard({ ...props }: HoverCardProps) {
  return <PreviewCardPrimitive.Root data-slot="hover-card" {...props} />;
}

function HoverCardTrigger({ ...props }: HoverCardTriggerProps) {
  return (
    <PreviewCardPrimitive.Trigger data-slot="hover-card-trigger" {...props} />
  );
}

function HoverCardContent({
  className,
  side = "bottom",
  sideOffset = 4,
  align = "center",
  alignOffset = 4,
  container,
  ...props
}: HoverCardContentProps) {
  const portalContainer = useJkPortalContainer(container);

  return (
    <PreviewCardPrimitive.Portal
      data-slot="hover-card-portal"
      container={portalContainer ?? undefined}
    >
      <PreviewCardPrimitive.Positioner
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
        className="isolate z-50"
      >
        <PreviewCardPrimitive.Popup
          data-slot="hover-card-content"
          className={cn(
            "z-50 w-64 origin-(--transform-origin) rounded-lg bg-popover p-2.5 text-sm text-popover-foreground shadow-md ring-1 ring-foreground/10 outline-hidden duration-100 motion-reduce:animate-none data-[side=bottom]:slide-in-from-top-2 data-[side=inline-end]:slide-in-from-left-2 data-[side=inline-start]:slide-in-from-right-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95",
            className,
          )}
          {...props}
        />
      </PreviewCardPrimitive.Positioner>
    </PreviewCardPrimitive.Portal>
  );
}

export { HoverCard, HoverCardContent, HoverCardTrigger };

import type { PreviewCard as PreviewCardPrimitive } from "@base-ui/react/preview-card";

export type HoverCardProps = PreviewCardPrimitive.Root.Props;
export type HoverCardTriggerProps = PreviewCardPrimitive.Trigger.Props;
export type HoverCardPortalProps = PreviewCardPrimitive.Portal.Props;
export type HoverCardContentProps = PreviewCardPrimitive.Popup.Props &
  Pick<
    PreviewCardPrimitive.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset"
  > &
  Pick<PreviewCardPrimitive.Portal.Props, "container">;

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...classes: ClassValue[]) {
  return twMerge(clsx(classes));
}

"use client";

import {
  createContext,
  createElement,
  type ReactNode,
  type RefObject,
  useContext,
} from "react";

export type JkPortalContainer =
  | HTMLElement
  | ShadowRoot
  | RefObject<HTMLElement | ShadowRoot | null>
  | null
  | undefined;

const JkPortalContainerContext = createContext<JkPortalContainer>(undefined);

export function JkPortalContainerProvider({
  container,
  children,
}: {
  container: JkPortalContainer;
  children: ReactNode;
}) {
  return createElement(
    JkPortalContainerContext.Provider,
    { value: container },
    children,
  );
}

export function useJkPortalContainer(
  override?: JkPortalContainer,
): JkPortalContainer {
  const ctx = useContext(JkPortalContainerContext);
  if (override !== undefined) return override ?? undefined;
  return ctx ?? undefined;
}
